const ROOT='/home/yimu/Desktop/leetcode/强化学习';
const command=(s)=>`${ROOT}/run.sh ${s}`;
const LESSONS=[
{title:'先分清三条学习路线',short:'学习地图',day:1,tag:'01 / 建立坐标',intro:`<h3>你已经会模仿。现在，加入反馈。</h3><p class="lead">行为克隆让模型接近示范动作；强化学习用奖励衡量长期结果，再更新策略。二者都可以使用神经网络，关键差别在学习信号和数据来源。</p><div class="split"><div class="card"><h4>你熟悉的 BC</h4><p>观测 + 示范动作 → 预测误差 → 更新策略<br>驾驶日志中“这个场景应该怎么开”。</p></div><div class="card"><h4>接下来学习的 RL</h4><p>状态 + 动作 + 奖励 + 后继状态 → 价值 / 优势 → 更新策略<br>“怎样的选择能带来更好的闭环结果”。</p></div></div><div class="callout">本课程共用一个小任务：给摆杆施加连续力矩，让它摆起并保持直立。先读懂算法，再把观测与动作替换成驾驶或机器人接口。</div>`,demo:'map',codeKey:'entry',codeNote:'先认入口：在线算法用 Stable-Baselines3 运行，CleanRL 单文件供学习；离线 BC/IQL 是本项目的确定性教学实现。',cmd:command('evaluate --episodes 20 --out '+ROOT+'/runs/tutorial/random'),question:'SAC 会重复学习旧策略采集的数据，因此它一定是离线强化学习吗？',options:['是，只要有经验池就是离线学习','不是，训练时是否继续采集数据才区分在线与离线','是，off-policy 与 offline 是同义词'],answer:1,explain:'SAC 的经验池让它属于 off-policy；只要训练中仍与环境交互采集新样本，它仍是在线强化学习。'},
{title:'奖励，如何变成长期价值',short:'奖励与价值',day:1,tag:'02 / 强化学习基础',intro:`<h3>一次动作，不只影响这一帧。</h3><p class="lead">MDP 用状态、动作、转移、奖励和折扣因子描述决策。智能体追求的是折扣累计回报，而不只是即时奖励。</p><div class="formula">Gₜ = rₜ + γrₜ₊₁ + γ²rₜ₊₂ + …</div><div class="split"><div class="card"><h4>V(s)：这个状态有多好？</h4><p>跟随当前策略，从状态 s 出发的预期回报。驾驶中可以理解为“目前局面有多有利”。</p></div><div class="card"><h4>Q(s,a)：先这样做有多好？</h4><p>先在状态 s 执行动作 a，再跟随策略的预期回报。A(s,a)=Q(s,a)−V(s) 衡量相对优势。</p></div></div><div class="callout orange">实际观测不一定等于完整状态。单帧图像可能缺少速度和遮挡信息；驾驶任务往往需要历史帧或记忆。本课先用低维状态隔离这个难点。</div>`,demo:'return',codeKey:'data',codeNote:'采集时保存后继观测和两种结束标记。真正终止不 bootstrap；纯时间限制截断一般仍使用后继状态价值。',cmd:command('collect --steps 1000 --data '+ROOT+'/runs/tutorial/random-data.npz --out '+ROOT+'/runs/tutorial/collect'),question:'回报为 −100，是否一定比 −500 差？',options:['是，绝对值越小越差','不能比较负数回报','不是，同一奖励定义下 −100 比 −500 更高'],answer:2,explain:'目标是最大化回报。在 Pendulum 中，偏角、角速度和控制开销带来负奖励；更接近 0 通常更好，但应在相同环境和评估设置下比较。'},
{title:'PPO：让好动作更可能发生',short:'在线学习 · PPO',day:1,tag:'03 / ON-POLICY',intro:`<h3>先采一批，再稳一点地更新。</h3><p class="lead">Actor 输出动作分布，Critic 估计 V。PPO 收集近期策略的 rollout，通过 GAE 估计优势，然后用旧动作概率作为参照进行多轮更新。</p><div class="flow"><span>策略采样</span><b>→</b><span>rollout</span><b>→</b><span>GAE / 优势</span><b>→</b><span>clip loss</span><b>→</b><span>新策略</span></div><div class="formula">L = E[min(ρA, clip(ρ, 1−ε, 1+ε)A)]</div><p class="small">ρ=π新(a|s)/π旧(a|s)。优化器通常最小化 −L。ε 常取 0.2。下面演示只看一个样本的策略目标，不含 value loss 或 entropy。</p><div class="callout">clip 限制的是更新激励，不是对参数变化、KL 或物理行为的严格安全约束。近期 rollout 可以更新多轮，但不能无限复用。</div>`,demo:'ppo',codeKey:'ppo',codeNote:'阅读顺序：rollout → GAE → 概率比 → clipped policy loss。这里展示逐轮实验中带详细注释的 PPO 教学实现；标准多epoch实现可对照本地 CleanRL。',cmd:command('train --algo ppo --steps 5000 --seed 0 --out '+ROOT+'/runs/tutorial/ppo'),question:'PPO 中优势 A 为正，概率比已经大于 1+ε，继续增大该动作概率会怎样？',options:['该样本 clipped 目标不再因此增加','目标会一直线性增加','环境会自动拒绝该动作'],answer:0,explain:'正优势样本在上界之后，min 选择裁剪分支，策略目标对这个概率比不再增加。负优势的激励方向相反。'},
{title:'SAC：复用经验，也保留探索',short:'在线学习 · SAC',day:2,tag:'04 / OFF-POLICY',intro:`<h3>经验池，让一次交互被多次利用。</h3><p class="lead">SAC 学习随机策略和双 Q 网络。经验池复用历史 transition；目标网络缓慢跟随；Actor 在追求 Q 的同时获得熵奖励。</p><div class="formula">Actor 目标：最大化 E[Q(s,a) − α log π(a|s)]</div><div class="split"><div class="card"><h4>双 Q + 目标网络</h4><p>使用两个 Q 的较小值缓解过高估计。目标网络通过软更新减小训练目标快速变化。</p></div><div class="card"><h4>温度 α</h4><p>调节奖励与随机性之间的权衡。自动温度调节让策略熵接近目标，不等于随机性越大越好。</p></div></div><div class="callout orange">连续动作通常经过 tanh 压到动作范围。计算 log π 时要考虑变量变换；忽略这一项会改变学习目标。</div>`,demo:'sac',codeKey:'sac',codeNote:'将 SAC 的经验池与 PPO 的 rollout 对照。这里是逐轮实验的详细注释实现；Actor通过Q与熵学习，不直接拟合教师动作。',cmd:command('train --algo sac --steps 5000 --seed 0 --out '+ROOT+'/runs/tutorial/sac'),question:'普通 SAC 直接在固定日志上训练，最需要警惕什么？',options:['它没有神经网络','策略可能利用数据外动作的虚高 Q 值','经验池会自动补齐日志中缺失的行为'],answer:1,explain:'固定数据无法为新动作补充真实反馈。策略主动追求高 Q 时，可能利用函数逼近在数据外的错误估计；off-policy 能力不自动解决这个问题。'},
{title:'冻结数据，切换到离线学习',short:'构建离线数据',day:2,tag:'05 / DATASET',intro:`<h3>从现在开始，训练只能使用这份经验。</h3><p class="lead">在线训练可持续补充数据；离线训练的数据集固定。数据覆盖决定策略能可靠学到什么。随机、中途和较好行为的混合，往往比“只有专家”更能揭示算法差异。</p><div class="flow"><span>行为策略</span><b>→</b><span>采集轨迹</span><b>→</b><span>冻结数据</span><b>→</b><span>训练 BC / IQL</span></div><div class="table-wrap"><table><tr><th>字段</th><th>内容</th></tr><tr><td>observation / action</td><td>决策依据与实际执行动作</td></tr><tr><td>reward / next_observation</td><td>结果反馈与转移后观测</td></tr><tr><td>terminated / truncated</td><td>任务终止 / 外部时间限制</td></tr><tr><td>episode / metadata</td><td>轨迹边界、行为来源与哈希</td></tr></table></div><div class="callout">离线算法可以进入独立环境评估，但评估交互不能写回训练数据。只保存图片和专家动作的 BC 数据，还缺少直接做价值学习所需的奖励与转移信息。</div>`,demo:'dataset',codeKey:'data',codeNote:'下面命令采集现有 SAC 短训练策略。它只是流程测试策略，未经充分训练，不能称作专家。先运行上一课的 SAC 命令。',cmd:command('collect --algo sac --model '+ROOT+'/runs/tutorial/sac/model.zip --steps 20000 --data '+ROOT+'/runs/tutorial/sac-data.npz --out '+ROOT+'/runs/tutorial/collect-sac'),question:'离线 IQL 训练期间，哪一种做法保持了离线设定？',options:['评估轨迹不写回训练集，只报告表现','每次评估后把新轨迹加入经验池','让 Actor 自动调用环境补充高 Q 动作'],answer:0,explain:'独立的在线评估与离线训练并不矛盾；关键是评估产生的数据不再影响训练集。对评估回报反复调参仍可能造成评估集过拟合。'},
{title:'BC：先建立你熟悉的基线',short:'离线基线 · BC',day:3,tag:'06 / BEHAVIOR CLONING',intro:`<h3>先回答：只模仿，会学成什么？</h3><p class="lead">本项目的 BC 直接最小化动作均方误差：将观测输入策略，拟合数据动作。确定性输出经过 tanh，并乘 2 对应摆杆力矩范围。</p><div class="formula">L<sub>BC</sub> = E<sub>(s,a)∼D</sub>[(π(s) − a)²]</div><div class="split"><div class="card"><h4>混合数据的挑战</h4><p>同一局面里，好动作和坏动作都可能被等权模仿。多模态动作还可能被回归成一个不理想的均值。</p></div><div class="card"><h4>闭环分布偏移</h4><p>小误差把策略带到日志没有覆盖的状态。离线动作误差很低，闭环表现仍可能不好。</p></div></div>`,demo:'bc',codeKey:'bc',codeNote:'BC 与 IQL 使用相同的确定性策略网络。IQL 的策略更新会为这些动作误差乘上优势权重。',cmd:command('train --algo bc --data '+ROOT+'/runs/tutorial/sac-data.npz --steps 2000 --out '+ROOT+'/runs/tutorial/bc'),question:'验证集动作 MSE 降低，能否单独证明闭环控制更好？',options:['能，所有损失都等于闭环回报','不能，还要独立闭环评估状态偏移与累计回报','能，只要数据集足够大'],answer:1,explain:'动作误差只评估数据覆盖状态上的拟合。部署策略诱导的新状态分布可能不同，因此必须独立评估闭环行为与回报。'},
{title:'IQL：用价值挑选值得模仿的动作',short:'离线学习 · IQL',day:3,tag:'07 / IMPLICIT Q-LEARNING',intro:`<h3>把“每个动作都学”，变成“好动作多学”。</h3><p class="lead">IQL 用数据中的动作学习 Q，用偏向高价值动作的 expectile 学习 V，再通过优势加权 BC 提取策略。价值更新不需要查询当前策略采样的数据外动作的 Q。</p><div class="flow"><span>V：expectile 回归</span><b>→</b><span>Q：r + γV(s′)</span><b>→</b><span>Actor：加权 BC</span></div><div class="formula">w = min(exp(β[Q(s,a) − V(s)]), 100)</div><div class="callout">本地实现用 τ=0.7、β=3 和确定性 Actor。优势权重上限 100。不同实现可能把温度写成除法，比较参数前要先对照公式。</div><div class="callout orange">expectile 不是分位数。它是非对称平方损失的最优位置；τ 越大越强调低估高价值动作的代价。数据覆盖不足时，IQL 也不保证超越 BC。</div>`,demo:'iql',codeKey:'iql',codeNote:'请按 V → Q → Actor 的顺序阅读本地实现，再对照 CORL。目标网络不参与梯度，优势权重也 detach。',cmd:command('train --algo iql --data '+ROOT+'/runs/tutorial/sac-data.npz --steps 5000 --out '+ROOT+'/runs/tutorial/iql'),question:'IQL 的策略更新和 BC 最直接的联系是什么？',options:['IQL 不再使用数据中的动作','IQL 用优势给行为克隆误差加权','IQL 必须在线采集每个动作的结果'],answer:1,explain:'本项目的确定性 IQL 最小化优势加权动作 MSE。较高优势的数据动作有更大权重；Q、V 的学习负责产生这些权重。'},
{title:'把实验结果带回真实问题',short:'评估与复盘',day:3,tag:'08 / PUT IT TOGETHER',intro:`<h3>读懂结果，而不只是跑完代码。</h3><p class="lead">PPO/SAC 比较时同时报告交互步数、更新次数和耗时；BC/IQL 比较时固定数据、网络和评估协议。loss 下降与回报提高是两件事。</p><div class="table-wrap"><table><tr><th>方法</th><th>学习信号</th><th>训练采新数据</th><th>关键限制</th></tr><tr><td>PPO</td><td>近期 rollout 的优势</td><td>是</td><td>近期数据不能无限复用</td></tr><tr><td>SAC</td><td>Q + 熵</td><td>通常是</td><td>普通 SAC 不专门解决离线分布偏移</td></tr><tr><td>BC</td><td>示范动作误差</td><td>否</td><td>混合质量、闭环偏移</td></tr><tr><td>IQL</td><td>价值 + 优势加权模仿</td><td>否</td><td>仍受固定数据覆盖限制</td></tr></table></div><div class="callout">迁移到驾驶或具身：先定义观测与动作，再检查奖励是否表达任务、日志是否覆盖关键行为、终止语义是否正确，最后做独立闭环评估。</div>`,demo:'results',codeKey:'evaluation',codeNote:'默认固定评估种子 10000–10019，报告回报均值和标准差。正式比较请训练多个种子；不能将两个测试回合当作算法基准。',cmd:command('evaluate --algo iql --model '+ROOT+'/runs/tutorial/iql/model.pt --episodes 20 --video --out '+ROOT+'/runs/tutorial/iql-eval'),question:'某次实验 IQL 不如 BC，最合理的下一步是什么？',options:['删除失败结果，只展示最好种子','确认数据质量、覆盖、奖励和训练预算，并用相同协议复核','直接认定所有离线强化学习都无效'],answer:1,explain:'保留原始结果，检查实现与实验条件，再用多个种子复核。算法优劣依赖数据与任务，不能从一次短实验得出普遍结论。'}
];

