const SOURCES={"entry": {"file": "lab.py", "start": 20, "text": " 20  def main():\n 21      # train更新模型；collect只采数据；evaluate冻结参数；plot只读日志。\n 22      p=argparse.ArgumentParser(description=__doc__)\n 23      p.add_argument('command',choices=['train','collect','evaluate','plot'])\n 24      p.add_argument('--algo',choices=['ppo','sac','bc','iql'],default='sac')\n 25      p.add_argument('--steps',type=int,default=5000)\n 26      p.add_argument('--seed',type=int,default=0)\n 27      p.add_argument('--video',action='store_true'); p.add_argument('--model'); p.add_argument('--data',default='dataset.npz')\n 28      p.add_argument('--out',default='runs/demo'); p.add_argument('--episodes',type=int,default=20)\n 29      a=p.parse_args(); out=Path(a.out); out.mkdir(parents=True,exist_ok=True)\n 30      # 固定初始化随机种子，并限制PyTorch内部线程，避免CPU过载。\n 31      guard(); torch.set_num_threads(1); torch.manual_seed(a.seed); np.random.seed(a.seed); random.seed(a.seed)\n 32      # 观测=[cosθ,sinθ,角速度]，动作是[-2,2]力矩。渲染只在--video时开启。\n 33      env=gym.make('Pendulum-v1',render_mode='rgb_array' if a.video else None);\n 34      if a.video: env=gym.wrappers.RecordVideo(env,str(out/'videos'),episode_trigger=lambda ep: ep==0)\n 35      env.action_space.seed(a.seed)\n 36      policy=net(3,1)\n 37      # PPO/SAC的zip由SB3加载；BC/IQL的pt保存本地Actor权重。\n 38      if a.model:\n 39          if a.algo in ['ppo','sac']:\n 40              model={'ppo':PPO,'sac':SAC}[a.algo].load(a.model,device='cpu')\n 41          else: policy.load_state_dict(torch.load(a.model,weights_only=True))\n 42      # 无--model时是随机策略，不是已经训练过的RL策略。\n 43      def act(s):\n 44          if not a.model: return env.action_space.sample()\n 45          if a.algo in ['ppo','sac']: return model.predict(s,deterministic=True)[0]\n 46          with torch.no_grad(): return (2*torch.tanh(policy(torch.tensor(s,dtype=torch.float32)))).numpy()"}, "data": {"file": "lab.py", "start": 107, "text": "107      elif a.command=='collect':\n108          # 转移采集保存真实后继状态，再处理reset；不能把下一局初态当作s′。\n109          data={k:[] for k in ['observation','action','reward','next_observation','terminated','truncated','episode']}\n110          s,_=env.reset(seed=a.seed); ep=0\n111          for _ in range(a.steps):\n112              u=act(s); ns,r,t,tr,_=env.step(u)\n113              for k,val in zip(data,[s,u,r,ns,t,tr,ep]): data[k].append(val)\n114              s=ns\n115              # terminated=任务结束；truncated=时间限制；两者都需要reset但bootstrap语义不同。\n116              if t or tr: ep+=1; s,_=env.reset()\n117          np.savez_compressed(a.data,**{k:np.array(v) for k,v in data.items()})\n118          Path(a.data+'.json').write_text(json.dumps({'source':vars(a),'sha256':hashlib.sha256(Path(a.data).read_bytes()).hexdigest()},indent=2))"}, "bc": {"file": "lab.py", "start": 74, "text": " 74              for step in range(a.steps):\n 75                  if step%100==0: guard()\n 76                  # 在固定数据上有放回采样；离线训练不调用env.step补新经验。\n 77                  idx=torch.randint(len(s),(256,)); x,u,y,z,done=s[idx],ac[idx],r[idx],ns[idx],t[idx]\n 78                  # 普通BC每条示范权重为1；IQL根据优势重新加权。\n 79                  weight=torch.ones((256,1))\n 80                  if a.algo=='iql':\n 81                      # 偏向较高价值的 expectile 拟合数据内动作的价值。\n 82                      # target不反传：取数据动作的双Q较小值，减少过高估计。\n 83                      with torch.no_grad(): target=torch.minimum(tq1(torch.cat([x,u],1)),tq2(torch.cat([x,u],1)))\n 84                      # Expectile：δ>0权重0.7，δ≤0权重0.3，拟合数据内较好动作的价值。\n 85                      diff=target-v(x); vl=(torch.where(diff>0,.7,.3)*diff.square()).mean()\n 86                      # 清梯度→反传→更新V；这对应IL中熟悉的一个监督训练step。\n 87                      vo.zero_grad(); vl.backward(); vo.step()\n 88                      # Bellman目标用更新后的V；时间截断仍bootstrap，真正终止才乘0。\n 89                      # β=3放大正优势；上限100避免指数权重极端增大。\n 90                      with torch.no_grad(): bellman=y+.99*(1-done)*v(z); weight=torch.exp(3*(target-v(x))).clamp(max=100)\n 91                      # 拼接[s,a]得到[B,4]，双Q都拟合同一个Bellman监督目标。\n 92                      xu=torch.cat([x,u],1); ql=((q1(xu)-bellman).square()+(q2(xu)-bellman).square()).mean()\n 93                      # Q更新后再软更新目标Q：target←0.995target+0.005Q。\n 94                      qo.zero_grad(); ql.backward(); qo.step()\n 95                      with torch.no_grad():\n 96                          for source,target_net in [(q1,tq1),(q2,tq2)]:\n 97                              for src,dst in zip(source.parameters(),target_net.parameters()): dst.lerp_(src,.005)\n 98                  # 确定性优势加权 BC；对应 CORL deterministic actor 变体。\n 99                  # IL类比：BC拟合动作；IQL同样拟合动作，但好动作的误差权重更大。\n100                  # Actor输出tanh×2映射到力矩范围；weights已经detach，不反传到Q/V。\n101                  loss=(weight*(2*torch.tanh(policy(x))-u).square()).mean()\n102                  # loss.backward计算所有Actor参数梯度；Adam实际使用一/二阶矩更新。\n103                  po.zero_grad(); loss.backward(); po.step()\n104                  if step%100==0: log.append({'update':step,'actor_loss':loss.item()})\n105              torch.save(policy.state_dict(),out/'model.pt'); (out/'loss.json').write_text(json.dumps(log))"}, "iql": {"file": "live_engine.py", "start": 303, "text": "303      def offline_update(self):\n304          s,a,r,ns,done = self.batch()\n305          # 固定数据用于BC监督或IQL价值学习。评估轨迹不在self.buffer中。\n306          updates, losses = [], {}\n307          weights = torch.ones_like(r)\n308          sample = dict(state=s[0].tolist(), next_state=ns[0].tolist(), action=float(a[0,0]),reward=float(r[0,0]),terminated=bool(done[0,0]))\n309          if self.algo == 'iql':\n310              with torch.no_grad():\n311                  q_data = torch.minimum(self.tq1(torch.cat([s,a],1)),self.tq2(torch.cat([s,a],1)))\n312              value = self.value(s)\n313              diff = q_data-value\n314              asym = torch.where(diff>0,.7,.3)\n315              vl = (asym*diff.square()).mean()\n316              sample.update(q=float(q_data[0,0]),v_before=float(value[0,0].detach()),diff=float(diff[0,0].detach()),\n317                            expectile_weight=float(asym[0,0]),expectile_sample_loss=float((asym*diff.square())[0,0].detach()))\n318              updates.append(optimizer_step(vl,self.v_opt,self.value[-1].bias,'V.output.bias[0]'))\n319              with torch.no_grad():\n320                  target = r+.99*(1-done)*self.value(ns)\n321                  advantage = q_data-self.value(s)\n322                  weights = torch.exp(3*advantage).clamp(max=100)\n323              xu=torch.cat([s,a],1)\n324              ql=((self.q1(xu)-target).square()+(self.q2(xu)-target).square()).mean()\n325              updates.append(optimizer_step(ql,self.q_opt,self.q1[-1].bias,'Q1.output.bias[0]（Q1/Q2联合）'))\n326              with torch.no_grad():\n327                  for src,dst in [(self.q1,self.tq1),(self.q2,self.tq2)]:\n328                      for p,tp in zip(src.parameters(),dst.parameters()):tp.lerp_(p,.005)\n329              sample.update(q_target=float(target[0,0]),advantage=float(advantage[0,0]),weight=float(weights[0,0]))\n330              losses.update(value=vl.item(),q=ql.item())\n331          prediction=self.actor.deterministic(s)\n332          mse=(prediction-a).square()\n333          actor_loss=(weights*mse).mean()\n334          # 与IL的链式法则完全相同，仅IQL多一个已detach的样本权重w。\n335          # π=2tanh(μ)，所以∂π/∂b=2(1−(π/2)²)。\n336          d_action = 2 * (1-(prediction.detach()/2).square())\n337          grad_samples = 2 * weights * (prediction.detach()-a) * d_action\n338          gradient_check = dict(formula='g_b=mean(2w(π−a)×2(1−(π/2)²))；BC中w=1',\n339                                sample_error=float((prediction.detach()-a)[0,0]),\n340                                sample_daction=float(d_action[0,0]),sample_weight=float(weights[0,0]),\n341                                sample_gradient=float(grad_samples[0,0]),analytic_batch_gradient=float(grad_samples.mean()))\n342          sample.update(prediction=float(prediction[0,0].detach()),mse=float(mse[0,0].detach()),\n343                        weight=float(weights[0,0]),weighted_error=float((weights*mse)[0,0].detach()))\n344          updates.append(optimizer_step(actor_loss,self.actor_opt,self.actor.mean.bias,'Actor.mean.bias[0]'))\n345          losses['actor']=actor_loss.item()\n346          return dict(algorithm=self.algo.upper(),source='初始化冻结的2048条脚本教师+随机转移',batch=64,\n347                      data_hash=self.data_hash,sample=sample,losses=losses,updates=updates,gradient_check=gradient_check,\n348                      formulas=['BC: L=mean((2tanh(μ(s))−a数据)²)' ] if self.algo=='bc' else\n349                               ['V: δ=min(Qtarget1,Qtarget2)−V；L=mean(|0.7−1[δ<0]|δ²)',\n350                                'Q: y=r+0.99(1−terminated)V新(s′)；L=mean((Q1−y)²+(Q2−y)²)',\n351                                'target Q ← 0.995 target Q+0.005 Q新',\n352                                'Actor: w=min(exp(3(Qtarget数据−V新)),100)；L=mean(w(π(s)−a数据)²)'],\n353                      note='每轮V、Q、Actor各更新一次。BC只更新Actor。训练不再与环境交互；每轮之后的独立仿真只做评估。')\n354  "}, "ppo": {"file": "live_engine.py", "start": 223, "text": "223      def ppo_update(self):\n224          \"\"\"与 IL 的区别：动作是旧策略自己采样的，标签是 GAE 优势而非专家动作。\n225  \n226          用未压缩高斯 z 计算 log概率；执行动作2*tanh(z)。同一z的新旧动作变换\n227          雅可比会抵消，因此概率比可以在z空间精确计算。单轮只做一次联合梯度更新，连续4轮复用同一rollout。\n228          \"\"\"\n229          # 同一个rollout复用4次，每次只做一个step并立即仿真。\n230          # 因而第1步ratio=1，后续步ratio随策略改变，clipping真正参与更新。\n231          if self.ppo_cache is None or self.ppo_epoch == 4:\n232              rows = []\n233              for _ in range(256):\n234                  s = torch.tensor(self.obs, dtype=torch.float32).unsqueeze(0)\n235                  with torch.no_grad():\n236                      dist = self.actor.distribution(s)\n237                      z = dist.sample()\n238                      action = (2 * torch.tanh(z))[0].numpy()\n239                      old_log = dist.log_prob(z).sum(-1).item()\n240                      value = self.value(s).item()\n241                  nxt, r, term, trunc, _ = self.env.step(action)\n242                  with torch.no_grad():\n243                      next_value = 0. if term else self.value(torch.tensor(nxt,dtype=torch.float32).unsqueeze(0)).item()\n244                  rows.append(dict(s=self.obs.copy(), z=z[0].numpy(), reward=r, value=value,\n245                                   next_value=next_value, logp=old_log, term=term, trunc=trunc))\n246                  self.obs = nxt\n247                  if term or trunc:\n248                      self.obs, _ = self.env.reset()\n249              # delta=r+gamma*V(s')-V(s)。截断可bootstrap，但GAE不能跨新episode串接。\n250              advantages = []\n251              gae = 0.\n252              for row in reversed(rows):\n253                  delta = row['reward'] + self.gamma * row['next_value'] - row['value']\n254                  gae = delta + self.gamma * .95 * (not(row['term'] or row['trunc'])) * gae\n255                  advantages.append(gae)\n256              advantages.reverse()\n257              self.ppo_cache = (rows, advantages)\n258              self.ppo_epoch = 0\n259          rows, advantages = self.ppo_cache\n260          self.ppo_epoch += 1\n261          raw_adv = torch.tensor(advantages, dtype=torch.float32)\n262          values = torch.tensor([x['value'] for x in rows], dtype=torch.float32)\n263          targets = raw_adv + values\n264          adv = (raw_adv - raw_adv.mean()) / (raw_adv.std(unbiased=False) + 1e-8)\n265          s = torch.tensor(np.array([x['s'] for x in rows]), dtype=torch.float32)\n266          z = torch.tensor(np.array([x['z'] for x in rows]), dtype=torch.float32)\n267          old_log = torch.tensor([x['logp'] for x in rows], dtype=torch.float32)\n268          # 所有256样本构成一批。同rollout第1次更新前ratio=1，之后由新旧策略差异决定。\n269          dist = self.actor.distribution(s)\n270          logp = dist.log_prob(z).sum(-1)\n271          ratio = torch.exp(logp-old_log)\n272          clipped = ratio.clamp(.8,1.2)\n273          surrogate = torch.minimum(ratio*adv,clipped*adv)\n274          policy_loss = -surrogate.mean()\n275          value_loss = (self.value(s).flatten()-targets).square().mean()\n276          entropy = dist.entropy().sum(-1).mean()\n277          loss = policy_loss + .5*value_loss - .01*entropy\n278          # 对Actor输出偏置b手推梯度：∂logN(z;μ,σ)/∂b=(z−μ)/σ²。\n279          # 正优势超过上界/负优势低于下界时，clipped目标变平，该样本梯度为0。\n280          # 未压缩高斯熵对均值偏置的导数为0。\n281          d_logp = ((z-dist.mean)/dist.variance).sum(-1).detach()\n282          active = ~(((adv>0)&(ratio.detach()>1.2))|((adv<0)&(ratio.detach()<.8)))\n283          actor_grad_samples = -adv * ratio.detach() * d_logp * active\n284          gradient_check = dict(formula='g_b=mean(−A×ρ×(z−μ)/σ²×未进入裁剪平坦区的掩码)',\n285                                sample_mu=float(dist.mean[0,0].detach()), sample_sigma=float(dist.stddev[0,0].detach()),\n286                                sample_dlogp=float(d_logp[0]), sample_gradient_active=bool(active[0]),sample_gradient=float(actor_grad_samples[0]),\n287                                analytic_batch_gradient=float(actor_grad_samples.mean()))\n288          sample = rows[0]\n289          sample_trace = dict(state=sample['s'].tolist(), latent_z=sample['z'].tolist(), action=(2*np.tanh(sample['z'])).tolist(), reward=sample['reward'], value=sample['value'], next_value=sample['next_value'],\n290                              delta=sample['reward']+.99*sample['next_value']-sample['value'],\n291                              gae=raw_adv[0].item(), target=targets[0].item(), advantage=adv[0].item(),\n292                              old_logp=old_log[0].item(), new_logp=logp[0].item(), ratio=ratio[0].item(),\n293                              clipped=clipped[0].item(), surrogate=surrogate[0].item())\n294          losses = dict(policy=policy_loss.item(), value=value_loss.item(), entropy=entropy.item(), total=loss.item(),clip_fraction=float(((ratio.detach()<.8)|(ratio.detach()>1.2)).float().mean()),rollout_epoch=self.ppo_epoch)\n295          update = optimizer_step(loss,self.ppo_opt,self.actor.mean.bias,'Actor.mean.bias[0]（与Critic联合）',.5)\n296          return dict(algorithm='PPO', source=f'旧策略在线采样256步；本rollout第{self.ppo_epoch}/4次更新', batch=256,\n297                      formulas=['δ=r+0.99V(s′)−V(s)', 'GAE=δ+0.99×0.95×下一个GAE（episode边界截断）',\n298                                'A标准化=(GAE−均值)/标准差；target=GAE+旧V',\n299                                'ρ=exp(logπ新−logπ旧)；Lπ=−mean(min(ρA,clip(ρ)A))',\n300                                'L=Lπ+0.5Lvalue−0.01H'],sample=sample_trace,losses=losses,updates=[update],gradient_check=gradient_check,\n301                      note='小网络PPO：同一rollout做4次全批更新，每次更新后独立仿真。第1步ratio=1，后续步可触发裁剪；用满4步后重新采样。熵项在未压缩高斯空间计算。')\n302  "}, "sac": {"file": "live_engine.py", "start": 355, "text": "355      def sac_update(self):\n356          self.collect(64)\n357          s,a,r,ns,done=self.batch()\n358          alpha=self.log_alpha.exp().detach()\n359          with torch.no_grad():\n360              na,nlogp=self.actor.sample(ns)\n361              soft_q=torch.minimum(self.tq1(torch.cat([ns,na],1)),self.tq2(torch.cat([ns,na],1)))-alpha*nlogp\n362              target=r+.99*(1-done)*soft_q\n363          qa=torch.cat([s,a],1)\n364          ql=((self.q1(qa)-target).square()+(self.q2(qa)-target).square()).mean()\n365          updates=[optimizer_step(ql,self.q_opt,self.q1[-1].bias,'Q1.output.bias[0]（Q1/Q2联合）')]\n366          # Actor更新期间冻结Q参数，但保留Q对动作的导数，使Actor仍能利用Q学习。\n367          for p in list(self.q1.parameters())+list(self.q2.parameters()):p.requires_grad_(False)\n368          action,logp=self.actor.sample(s)\n369          q_pi=torch.minimum(self.q1(torch.cat([s,action],1)),self.q2(torch.cat([s,action],1)))\n370          actor_loss=(alpha*logp-q_pi).mean()\n371          # Q对动作的导数由真实Q网络autograd得到，再手推Actor输出偏置的链式梯度。\n372          dq_da = torch.autograd.grad(q_pi.sum(),action,retain_graph=True)[0].detach()\n373          y=action.detach()/2\n374          d_action=2*(1-y.square())\n375          d_logp=4*y*(1-y.square())/(2*(1-y.square())+1e-6)\n376          grad_samples=alpha*d_logp-dq_da*d_action\n377          gradient_check=dict(formula='g_b=mean(α·∂logπ/∂μ − (∂Q/∂a)·2(1−tanh²z))',\n378                              sample_dlogp=float(d_logp[0,0]),sample_dqda=float(dq_da[0,0]),\n379                              sample_daction=float(d_action[0,0]),sample_gradient=float(grad_samples[0,0]),\n380                              analytic_batch_gradient=float(grad_samples.mean()))\n381          sample=dict(state=s[0].tolist(), next_state=ns[0].tolist(), action=float(a[0,0]), reward=float(r[0,0]),terminated=bool(done[0,0]),alpha=float(alpha),\n382                      next_logp=float(nlogp[0,0]),soft_next_q=float(soft_q[0,0]),q_target=float(target[0,0]),\n383                      logp=float(logp[0,0].detach()),q_pi=float(q_pi[0,0].detach()),\n384                      actor_sample_loss=float((alpha*logp-q_pi)[0,0].detach()))\n385          updates.append(optimizer_step(actor_loss,self.actor_opt,self.actor.mean.bias,'Actor.mean.bias[0]'))\n386          for p in list(self.q1.parameters())+list(self.q2.parameters()):p.requires_grad_(True)\n387          # 目标熵为−动作维度=−1。logp.detach：温度更新不再改变Actor。\n388          alpha_loss=-(self.log_alpha*(logp.detach()-1)).mean()\n389          updates.append(optimizer_step(alpha_loss,self.alpha_opt,self.log_alpha,'log_alpha[0]'))\n390          with torch.no_grad():\n391              for src,dst in [(self.q1,self.tq1),(self.q2,self.tq2)]:\n392                  for p,tp in zip(src.parameters(),dst.parameters()):tp.lerp_(p,.005)\n393          return dict(algorithm='SAC',source=f'在线经验池{len(self.buffer)}条；本轮新增64步',batch=64,\n394                      sample=sample,losses=dict(q=ql.item(),actor=actor_loss.item(),temperature=alpha_loss.item()),updates=updates,gradient_check=gradient_check,\n395                      formulas=['y=r+0.99(1−terminated)(min Qtarget(s′,a′)−αlogπ(a′|s′))',\n396                                'Q: mean((Q1−y)²+(Q2−y)²)', 'Actor: mean(αlogπ(a|s)−min Q新(s,a))',\n397                                '温度: −mean(logα×detach(logπ−1))；α=exp(logα)',\n398                                'target Q ← 0.995 target Q+0.005 Q新'],\n399                      note='同一轮Q、Actor、温度各做一次Adam更新，接着仿真。logπ是连续概率密度的对数，可以为正。')\n400  "}, "evaluation": {"file": "lab.py", "start": 119, "text": "119      elif a.command=='evaluate':\n120          # 与训练独立：固定20个种子，每回合200步；不更新模型，不向经验池回写。\n121          scores=[]\n122          for seed in range(10000,10000+a.episodes):\n123              s,_=env.reset(seed=seed); total=0\n124              for _ in range(200):\n125                  s,r,t,tr,_=env.step(act(s)); total+=r\n126                  if t or tr: break\n127              scores.append(total)\n128          # mean越大越好；std是回合间波动，不是多训练种子的置信区间。\n129          result={'returns':scores,'mean':float(np.mean(scores)),'std':float(np.std(scores))}; print(result)\n130          (out/'evaluation.json').write_text(json.dumps(result,indent=2))"}};
const ANNOTATED_SOURCES={"lab.py": "\"\"\"强化学习实验入口：在线算法阅读 cleanrl，离线算法对照 CORL。\"\"\"\nimport argparse, json, hashlib, random\nimport psutil\n\n# 系统可用内存检查；硬CPU/内存限制由run.sh的systemd scope设置。\ndef guard():\n    if psutil.virtual_memory().available < 8*1024**3:\n        raise RuntimeError(\"可用内存不足8GiB，停止，不自动恢复\")\nfrom pathlib import Path\nimport numpy as np\nimport torch\nfrom torch import nn\nimport gymnasium as gym\nfrom stable_baselines3 import PPO, SAC\n\n# IL/RL共用的MLP骨架：输入维度n→128→128→输出维度m。Actor为3→1，Q为4→1。\ndef net(n,m):\n    return nn.Sequential(nn.Linear(n,128),nn.ReLU(),nn.Linear(128,128),nn.ReLU(),nn.Linear(128,m))\n\ndef main():\n    # train更新模型；collect只采数据；evaluate冻结参数；plot只读日志。\n    p=argparse.ArgumentParser(description=__doc__)\n    p.add_argument('command',choices=['train','collect','evaluate','plot'])\n    p.add_argument('--algo',choices=['ppo','sac','bc','iql'],default='sac')\n    p.add_argument('--steps',type=int,default=5000)\n    p.add_argument('--seed',type=int,default=0)\n    p.add_argument('--video',action='store_true'); p.add_argument('--model'); p.add_argument('--data',default='dataset.npz')\n    p.add_argument('--out',default='runs/demo'); p.add_argument('--episodes',type=int,default=20)\n    a=p.parse_args(); out=Path(a.out); out.mkdir(parents=True,exist_ok=True)\n    # 固定初始化随机种子，并限制PyTorch内部线程，避免CPU过载。\n    guard(); torch.set_num_threads(1); torch.manual_seed(a.seed); np.random.seed(a.seed); random.seed(a.seed)\n    # 观测=[cosθ,sinθ,角速度]，动作是[-2,2]力矩。渲染只在--video时开启。\n    env=gym.make('Pendulum-v1',render_mode='rgb_array' if a.video else None);\n    if a.video: env=gym.wrappers.RecordVideo(env,str(out/'videos'),episode_trigger=lambda ep: ep==0)\n    env.action_space.seed(a.seed)\n    policy=net(3,1)\n    # PPO/SAC的zip由SB3加载；BC/IQL的pt保存本地Actor权重。\n    if a.model:\n        if a.algo in ['ppo','sac']:\n            model={'ppo':PPO,'sac':SAC}[a.algo].load(a.model,device='cpu')\n        else: policy.load_state_dict(torch.load(a.model,weights_only=True))\n    # 无--model时是随机策略，不是已经训练过的RL策略。\n    def act(s):\n        if not a.model: return env.action_space.sample()\n        if a.algo in ['ppo','sac']: return model.predict(s,deterministic=True)[0]\n        with torch.no_grad(): return (2*torch.tanh(policy(torch.tensor(s,dtype=torch.float32)))).numpy()\n    if a.command=='train':\n        # 在线训练会改变数据分布；IL常见的固定示范集与此不同。\n        if a.algo in ['ppo','sac']:\n            # 统一运行入口用成熟实现；原始算法逐行学习见 cleanrl 单文件。\n            model={'ppo':PPO,'sac':SAC}[a.algo]('MlpPolicy',env,seed=a.seed,device='cpu',verbose=1,tensorboard_log=str(out))\n            from stable_baselines3.common.callbacks import BaseCallback\n            class ResourceGuard(BaseCallback):\n                def _on_step(self):\n                    if self.num_timesteps % 100 == 0:\n                        try: guard()\n                        except RuntimeError:\n                            self.model.save(str(out/\"resource-stop\")); raise\n                    return True\n            # PPO的总步数按完整rollout取整，5000可能实际采6144步。\n            model.learn(a.steps,callback=ResourceGuard()); model.save(str(out/'model'))\n        else:\n            import copy\n            # 离线数据：s[B,3]、a[B,1]、r[B,1]、s′[B,3]、terminated[B,1]。\n            d=np.load(a.data); s,ac,r,ns,t=[torch.tensor(d[k],dtype=torch.float32) for k in ['observation','action','reward','next_observation','terminated']]\n            # 统一列向量，防止广播把[B]与[B,1]意外变成[B,B]。\n            r=r.reshape(-1,1); t=t.reshape(-1,1)\n            # Q(s,a)输入状态+动作；V(s)只输入状态；tq是缓慢跟随的目标网络。\n            q1=net(4,1); q2=net(4,1); v=net(3,1); tq1=copy.deepcopy(q1); tq2=copy.deepcopy(q2)\n            # Actor、双Q、V分开维护Adam；各自的梯度不会混用。\n            po=torch.optim.Adam(policy.parameters(),lr=3e-4)\n            qo=torch.optim.Adam(list(q1.parameters())+list(q2.parameters()),lr=3e-4); vo=torch.optim.Adam(v.parameters(),lr=3e-4)\n            log=[]\n            for step in range(a.steps):\n                if step%100==0: guard()\n                # 在固定数据上有放回采样；离线训练不调用env.step补新经验。\n                idx=torch.randint(len(s),(256,)); x,u,y,z,done=s[idx],ac[idx],r[idx],ns[idx],t[idx]\n                # 普通BC每条示范权重为1；IQL根据优势重新加权。\n                weight=torch.ones((256,1))\n                if a.algo=='iql':\n                    # 偏向较高价值的 expectile 拟合数据内动作的价值。\n                    # target不反传：取数据动作的双Q较小值，减少过高估计。\n                    with torch.no_grad(): target=torch.minimum(tq1(torch.cat([x,u],1)),tq2(torch.cat([x,u],1)))\n                    # Expectile：δ>0权重0.7，δ≤0权重0.3，拟合数据内较好动作的价值。\n                    diff=target-v(x); vl=(torch.where(diff>0,.7,.3)*diff.square()).mean()\n                    # 清梯度→反传→更新V；这对应IL中熟悉的一个监督训练step。\n                    vo.zero_grad(); vl.backward(); vo.step()\n                    # Bellman目标用更新后的V；时间截断仍bootstrap，真正终止才乘0。\n                    # β=3放大正优势；上限100避免指数权重极端增大。\n                    with torch.no_grad(): bellman=y+.99*(1-done)*v(z); weight=torch.exp(3*(target-v(x))).clamp(max=100)\n                    # 拼接[s,a]得到[B,4]，双Q都拟合同一个Bellman监督目标。\n                    xu=torch.cat([x,u],1); ql=((q1(xu)-bellman).square()+(q2(xu)-bellman).square()).mean()\n                    # Q更新后再软更新目标Q：target←0.995target+0.005Q。\n                    qo.zero_grad(); ql.backward(); qo.step()\n                    with torch.no_grad():\n                        for source,target_net in [(q1,tq1),(q2,tq2)]:\n                            for src,dst in zip(source.parameters(),target_net.parameters()): dst.lerp_(src,.005)\n                # 确定性优势加权 BC；对应 CORL deterministic actor 变体。\n                # IL类比：BC拟合动作；IQL同样拟合动作，但好动作的误差权重更大。\n                # Actor输出tanh×2映射到力矩范围；weights已经detach，不反传到Q/V。\n                loss=(weight*(2*torch.tanh(policy(x))-u).square()).mean()\n                # loss.backward计算所有Actor参数梯度；Adam实际使用一/二阶矩更新。\n                po.zero_grad(); loss.backward(); po.step()\n                if step%100==0: log.append({'update':step,'actor_loss':loss.item()})\n            torch.save(policy.state_dict(),out/'model.pt'); (out/'loss.json').write_text(json.dumps(log))\n        (out/'config.json').write_text(json.dumps(vars(a),indent=2))\n    elif a.command=='collect':\n        # 转移采集保存真实后继状态，再处理reset；不能把下一局初态当作s′。\n        data={k:[] for k in ['observation','action','reward','next_observation','terminated','truncated','episode']}\n        s,_=env.reset(seed=a.seed); ep=0\n        for _ in range(a.steps):\n            u=act(s); ns,r,t,tr,_=env.step(u)\n            for k,val in zip(data,[s,u,r,ns,t,tr,ep]): data[k].append(val)\n            s=ns\n            # terminated=任务结束；truncated=时间限制；两者都需要reset但bootstrap语义不同。\n            if t or tr: ep+=1; s,_=env.reset()\n        np.savez_compressed(a.data,**{k:np.array(v) for k,v in data.items()})\n        Path(a.data+'.json').write_text(json.dumps({'source':vars(a),'sha256':hashlib.sha256(Path(a.data).read_bytes()).hexdigest()},indent=2))\n    elif a.command=='evaluate':\n        # 与训练独立：固定20个种子，每回合200步；不更新模型，不向经验池回写。\n        scores=[]\n        for seed in range(10000,10000+a.episodes):\n            s,_=env.reset(seed=seed); total=0\n            for _ in range(200):\n                s,r,t,tr,_=env.step(act(s)); total+=r\n                if t or tr: break\n            scores.append(total)\n        # mean越大越好；std是回合间波动，不是多训练种子的置信区间。\n        result={'returns':scores,'mean':float(np.mean(scores)),'std':float(np.std(scores))}; print(result)\n        (out/'evaluation.json').write_text(json.dumps(result,indent=2))\n    else:\n        # actor_loss是训练拟合误差，不是环境回报；低loss不保证闭环效果好。\n        import matplotlib; matplotlib.use('Agg')\n        import matplotlib.pyplot as plt\n        log=json.loads((out/'loss.json').read_text()); plt.plot([x['update'] for x in log],[x['actor_loss'] for x in log]); plt.xlabel('updates'); plt.ylabel('actor loss'); plt.savefig(out/'loss.png')\n    env.close()\nif __name__=='__main__': main()\n", "live_engine.py": "\"\"\"逐轮强化学习教学引擎：所有动作、奖励与梯度均由真实 Gymnasium/PyTorch 计算。\n\n与 IL 对照：BC 的监督目标是数据动作；PPO 的监督信号是优势；\nSAC 用 Q 为可微策略提供方向；IQL 则把优势变成 BC 的样本权重。\n这是小网络、单批更新的教学配置，不是复现论文性能的 benchmark。\n一轮 = 每个相关优化器各更新一次，然后在同一初态跑完整的 200 步评估。\n评估数据绝不加入训练集，因而不会破坏 IQL/BC 的离线训练设定。\n\"\"\"\nimport copy\nimport hashlib\nimport json\nimport math\nimport time\nfrom pathlib import Path\n\nimport gymnasium as gym\nimport numpy as np\nimport psutil\nimport torch\nfrom torch import nn\nfrom torch.distributions import Normal\n\nROOT = Path(__file__).resolve().parent\n\n\ndef check_memory():\n    \"\"\"周期性守卫；CPU/RAM 硬上限由托管整个服务的 systemd cgroup 执行。\"\"\"\n    if psutil.virtual_memory().available < 8 * 1024 ** 3:\n        raise RuntimeError('可用内存低于 8GiB，已暂停；不自动重试。')\n\n\ndef mlp(n, m):\n    \"\"\"观测 [B,3] → 隐层 [B,32] → 输出。小网络让单轮更新足够快。\"\"\"\n    return nn.Sequential(nn.Linear(n, 32), nn.Tanh(), nn.Linear(32, 32), nn.Tanh(), nn.Linear(32, m))\n\n\nclass Actor(nn.Module):\n    \"\"\"与 IL 相同的观测编码骨架；RL 另外需要动作分布来计算 log π。\"\"\"\n    def __init__(self):\n        super().__init__()\n        self.features = nn.Sequential(nn.Linear(3, 32), nn.Tanh(), nn.Linear(32, 32), nn.Tanh())\n        self.mean = nn.Linear(32, 1)\n        self.log_std = nn.Parameter(torch.tensor([-0.5]))\n\n    def distribution(self, obs):\n        # 高斯分布是未压缩动作 z 的分布，标准差始终为正。\n        mean = self.mean(self.features(obs))\n        return Normal(mean, self.log_std.clamp(-5, 1).exp().expand_as(mean))\n\n    def deterministic(self, obs):\n        # IL/评估用确定性均值；tanh 后乘 2 对齐 Pendulum 力矩 [-2,2]。\n        return 2 * torch.tanh(self.distribution(obs).mean)\n\n    def sample(self, obs):\n        # SAC 用 rsample 重参数化，使 Q(s,a) 的梯度能经动作反传给 Actor。\n        dist = self.distribution(obs)\n        z = dist.rsample()\n        y = torch.tanh(z)\n        action = 2 * y\n        # 变量变换的雅可比包含 tanh 和乘2，不能将 z 的密度当作动作密度。\n        log_prob = (dist.log_prob(z) - torch.log(2 * (1 - y.square()) + 1e-6)).sum(-1, keepdim=True)\n        return action, log_prob\n\n\ndef optimizer_step(loss, optimizer, parameter, name, max_norm=None):\n    \"\"\"执行真实 Adam，并记录一个标量参数的完整计算链。\n\n    网络含上千参数，界面只手推输出偏置第一个元素；其余参数同样参与更新。\n    不能直接写 θ←θ−lr*g 冒充 Adam：它还包含一阶/二阶矩和偏置修正。\n    \"\"\"\n    optimizer.zero_grad(set_to_none=True)\n    before = parameter.detach().flatten()[0].item()\n    loss.backward()\n    raw_grad = parameter.grad.detach().flatten()[0].item()\n    norm = None\n    if max_norm is not None:\n        # PPO 全网络梯度裁剪；展示裁剪前和真正交给 Adam 的梯度。\n        params = [p for group in optimizer.param_groups for p in group['params']]\n        norm = float(nn.utils.clip_grad_norm_(params, max_norm))\n    grad = parameter.grad.detach().flatten()[0].item()\n    optimizer.step()\n    state = optimizer.state[parameter]\n    step = int(state['step'].item())\n    m = state['exp_avg'].flatten()[0].item()\n    v = state['exp_avg_sq'].flatten()[0].item()\n    group = optimizer.param_groups[0]\n    beta1, beta2 = group['betas']\n    # PyTorch Adam 默认无 weight_decay；按实际优化器超参逐项计算。\n    m_hat = m / (1 - beta1 ** step)\n    v_hat = v / (1 - beta2 ** step)\n    delta = -group['lr'] * m_hat / (math.sqrt(v_hat) + group['eps'])\n    after = parameter.detach().flatten()[0].item()\n    return dict(name=name, loss=float(loss.detach()), before=before, grad_raw=raw_grad,\n                grad=grad, grad_norm=norm, clip_norm=max_norm, lr=group['lr'], beta1=beta1,\n                beta2=beta2, eps=group['eps'], step=step, m=m, v=v, m_hat=m_hat,\n                v_hat=v_hat, predicted_delta=delta, actual_delta=after-before, after=after,\n                predicted_after=before+delta)\n\n\nclass Experiment:\n    def __init__(self, algo, seed=0, lr=0.003):\n        check_memory()\n        torch.set_num_threads(1)\n        torch.manual_seed(seed)\n        self.rng = np.random.default_rng(seed)\n        self.algo, self.seed, self.lr = algo, seed, lr\n        self.round = 0\n        self.ppo_cache = None\n        self.ppo_epoch = 0\n        self.gamma = 0.99\n        self.env = gym.make('Pendulum-v1')\n        self.env.action_space.seed(seed)\n        self.obs, _ = self.env.reset(seed=seed)\n        self.actor = Actor()\n        self.value = mlp(3, 1)\n        self.q1, self.q2 = mlp(4, 1), mlp(4, 1)\n        self.tq1, self.tq2 = copy.deepcopy(self.q1), copy.deepcopy(self.q2)\n        self.log_alpha = nn.Parameter(torch.tensor(math.log(.2)))\n        # PPO 的 Actor/Critic 联合更新；其他算法分别维护各自 Adam 状态。\n        self.ppo_opt = torch.optim.Adam(list(self.actor.parameters()) + list(self.value.parameters()), lr=lr)\n        self.actor_opt = torch.optim.Adam(self.actor.parameters(), lr=lr)\n        self.q_opt = torch.optim.Adam(list(self.q1.parameters()) + list(self.q2.parameters()), lr=lr)\n        self.v_opt = torch.optim.Adam(self.value.parameters(), lr=lr)\n        self.alpha_opt = torch.optim.Adam([self.log_alpha], lr=lr)\n        self.buffer = []\n        self.history = []\n        self.name = f'{time.time_ns()}_{algo}_s{seed}'\n        self.folder = ROOT / 'runs' / 'live' / self.name\n        self.folder.mkdir(parents=True)\n        # 冻结实际执行源码与关键依赖版本，避免未来修改后失去计算依据。\n        (self.folder/'live_engine.py').write_bytes(Path(__file__).read_bytes())\n        (self.folder/'dependencies.json').write_text(json.dumps(dict(torch=torch.__version__,gymnasium=gym.__version__,numpy=np.__version__),indent=2))\n        # 离线算法只在初始化生成一次训练数据。之后训练绝不调用 env.step。\n        if algo in ('bc', 'iql'):\n            self.make_offline_data()\n        if algo == 'sac':\n            self.collect(512, random_actions=True)\n        self.initial_hash = self.actor_hash()\n        baseline = self.evaluate()\n        self.history.append(dict(round=0, evaluation=baseline, trace=None, actor_hash=self.initial_hash))\n        self.persist(self.history[0])\n\n    def actor_hash(self):\n        data = b''.join(p.detach().cpu().numpy().tobytes() for p in self.actor.parameters())\n        return hashlib.sha256(data).hexdigest()\n\n    def make_offline_data(self):\n        \"\"\"用脚本控制器+随机动作生成固定转移。它是启发式教师，并非专家保证。\"\"\"\n        env = gym.make('Pendulum-v1')\n        obs, _ = env.reset(seed=self.seed + 200)\n        for _ in range(2048):\n            theta = math.atan2(float(obs[1]), float(obs[0]))\n            omega = float(obs[2])\n            # 近直立时 PD 稳定；其他角度按能量差泵能量。并混入30%随机行为。\n            energy = .5 * omega ** 2 + 15 * (math.cos(theta) - 1)\n            u = -8 * theta - 2 * omega if abs(theta) < .45 and abs(omega) < 2 else -0.3 * energy * omega\n            u = float(np.clip(u, -2, 2))\n            if self.rng.random() < .3:\n                u = float(self.rng.uniform(-2, 2))\n            action = np.array([u], dtype=np.float32)\n            nxt, reward, terminated, truncated, _ = env.step(action)\n            self.buffer.append((obs.copy(), action.copy(), reward, nxt.copy(), terminated, truncated))\n            obs = nxt\n            if terminated or truncated:\n                obs, _ = env.reset()\n        env.close()\n        np.savez_compressed(self.folder / 'frozen-data.npz',\n                            observation=np.array([x[0] for x in self.buffer]),\n                            action=np.array([x[1] for x in self.buffer]),\n                            reward=np.array([x[2] for x in self.buffer]),\n                            next_observation=np.array([x[3] for x in self.buffer]),\n                            terminated=np.array([x[4] for x in self.buffer]),\n                            truncated=np.array([x[5] for x in self.buffer]))\n        self.data_hash = hashlib.sha256((self.folder/'frozen-data.npz').read_bytes()).hexdigest()\n\n    def collect(self, count, random_actions=False):\n        \"\"\"SAC 在线经验池。评估另外用独立环境，绝不回流这里。\"\"\"\n        for _ in range(count):\n            with torch.no_grad():\n                obs = torch.tensor(self.obs, dtype=torch.float32).unsqueeze(0)\n                action = self.rng.uniform(-2, 2, (1,)).astype(np.float32) if random_actions else self.actor.sample(obs)[0][0].numpy()\n            nxt, r, term, trunc, _ = self.env.step(action)\n            self.buffer.append((self.obs.copy(), action.copy(), r, nxt.copy(), term, trunc))\n            self.obs = nxt\n            if term or trunc:\n                self.obs, _ = self.env.reset()\n        # 教学会话上限50轮，因此内存有界；离线数据不走这个分支。\n        self.buffer = self.buffer[-8192:]\n\n    def batch(self):\n        idx = self.rng.integers(0, len(self.buffer), size=64)\n        rows = [self.buffer[int(i)] for i in idx]\n        s = torch.tensor(np.array([x[0] for x in rows]), dtype=torch.float32)\n        a = torch.tensor(np.array([x[1] for x in rows]), dtype=torch.float32)\n        r = torch.tensor([x[2] for x in rows], dtype=torch.float32).unsqueeze(1)\n        ns = torch.tensor(np.array([x[3] for x in rows]), dtype=torch.float32)\n        done = torch.tensor([x[4] for x in rows], dtype=torch.float32).unsqueeze(1)\n        return s, a, r, ns, done\n\n    def evaluate(self):\n        \"\"\"每次参数更新后调用一次：固定种子10000、固定200步，公平对比行为变化。\n\n        不生成重负载光追视频。保存真实物理状态，由网页 canvas 逐帧画摆杆。\n        每个 frame 的奖励是执行该 frame 动作得到的奖励，最后一帧没有后续动作。\n        \"\"\"\n        env = gym.make('Pendulum-v1')\n        obs, _ = env.reset(seed=10000)\n        frames, total = [], 0.\n        for _ in range(200):\n            with torch.no_grad():\n                u = float(self.actor.deterministic(torch.tensor(obs, dtype=torch.float32).unsqueeze(0))[0, 0])\n            nxt, reward, term, trunc, _ = env.step(np.array([u], dtype=np.float32))\n            total += float(reward)\n            frames.append(dict(theta=math.atan2(float(obs[1]), float(obs[0])), omega=float(obs[2]),\n                               action=u, reward=float(reward), total=total))\n            obs = nxt\n            if term or trunc:\n                break\n        frames.append(dict(theta=math.atan2(float(obs[1]), float(obs[0])), omega=float(obs[2]), action=0., reward=0., total=total))\n        env.close()\n        return dict(seed=10000, return_=total, steps=len(frames)-1, frames=frames)\n\n    def ppo_update(self):\n        \"\"\"与 IL 的区别：动作是旧策略自己采样的，标签是 GAE 优势而非专家动作。\n\n        用未压缩高斯 z 计算 log概率；执行动作2*tanh(z)。同一z的新旧动作变换\n        雅可比会抵消，因此概率比可以在z空间精确计算。单轮只做一次联合梯度更新，连续4轮复用同一rollout。\n        \"\"\"\n        # 同一个rollout复用4次，每次只做一个step并立即仿真。\n        # 因而第1步ratio=1，后续步ratio随策略改变，clipping真正参与更新。\n        if self.ppo_cache is None or self.ppo_epoch == 4:\n            rows = []\n            for _ in range(256):\n                s = torch.tensor(self.obs, dtype=torch.float32).unsqueeze(0)\n                with torch.no_grad():\n                    dist = self.actor.distribution(s)\n                    z = dist.sample()\n                    action = (2 * torch.tanh(z))[0].numpy()\n                    old_log = dist.log_prob(z).sum(-1).item()\n                    value = self.value(s).item()\n                nxt, r, term, trunc, _ = self.env.step(action)\n                with torch.no_grad():\n                    next_value = 0. if term else self.value(torch.tensor(nxt,dtype=torch.float32).unsqueeze(0)).item()\n                rows.append(dict(s=self.obs.copy(), z=z[0].numpy(), reward=r, value=value,\n                                 next_value=next_value, logp=old_log, term=term, trunc=trunc))\n                self.obs = nxt\n                if term or trunc:\n                    self.obs, _ = self.env.reset()\n            # delta=r+gamma*V(s')-V(s)。截断可bootstrap，但GAE不能跨新episode串接。\n            advantages = []\n            gae = 0.\n            for row in reversed(rows):\n                delta = row['reward'] + self.gamma * row['next_value'] - row['value']\n                gae = delta + self.gamma * .95 * (not(row['term'] or row['trunc'])) * gae\n                advantages.append(gae)\n            advantages.reverse()\n            self.ppo_cache = (rows, advantages)\n            self.ppo_epoch = 0\n        rows, advantages = self.ppo_cache\n        self.ppo_epoch += 1\n        raw_adv = torch.tensor(advantages, dtype=torch.float32)\n        values = torch.tensor([x['value'] for x in rows], dtype=torch.float32)\n        targets = raw_adv + values\n        adv = (raw_adv - raw_adv.mean()) / (raw_adv.std(unbiased=False) + 1e-8)\n        s = torch.tensor(np.array([x['s'] for x in rows]), dtype=torch.float32)\n        z = torch.tensor(np.array([x['z'] for x in rows]), dtype=torch.float32)\n        old_log = torch.tensor([x['logp'] for x in rows], dtype=torch.float32)\n        # 所有256样本构成一批。同rollout第1次更新前ratio=1，之后由新旧策略差异决定。\n        dist = self.actor.distribution(s)\n        logp = dist.log_prob(z).sum(-1)\n        ratio = torch.exp(logp-old_log)\n        clipped = ratio.clamp(.8,1.2)\n        surrogate = torch.minimum(ratio*adv,clipped*adv)\n        policy_loss = -surrogate.mean()\n        value_loss = (self.value(s).flatten()-targets).square().mean()\n        entropy = dist.entropy().sum(-1).mean()\n        loss = policy_loss + .5*value_loss - .01*entropy\n        # 对Actor输出偏置b手推梯度：∂logN(z;μ,σ)/∂b=(z−μ)/σ²。\n        # 正优势超过上界/负优势低于下界时，clipped目标变平，该样本梯度为0。\n        # 未压缩高斯熵对均值偏置的导数为0。\n        d_logp = ((z-dist.mean)/dist.variance).sum(-1).detach()\n        active = ~(((adv>0)&(ratio.detach()>1.2))|((adv<0)&(ratio.detach()<.8)))\n        actor_grad_samples = -adv * ratio.detach() * d_logp * active\n        gradient_check = dict(formula='g_b=mean(−A×ρ×(z−μ)/σ²×未进入裁剪平坦区的掩码)',\n                              sample_mu=float(dist.mean[0,0].detach()), sample_sigma=float(dist.stddev[0,0].detach()),\n                              sample_dlogp=float(d_logp[0]), sample_gradient_active=bool(active[0]),sample_gradient=float(actor_grad_samples[0]),\n                              analytic_batch_gradient=float(actor_grad_samples.mean()))\n        sample = rows[0]\n        sample_trace = dict(state=sample['s'].tolist(), latent_z=sample['z'].tolist(), action=(2*np.tanh(sample['z'])).tolist(), reward=sample['reward'], value=sample['value'], next_value=sample['next_value'],\n                            delta=sample['reward']+.99*sample['next_value']-sample['value'],\n                            gae=raw_adv[0].item(), target=targets[0].item(), advantage=adv[0].item(),\n                            old_logp=old_log[0].item(), new_logp=logp[0].item(), ratio=ratio[0].item(),\n                            clipped=clipped[0].item(), surrogate=surrogate[0].item())\n        losses = dict(policy=policy_loss.item(), value=value_loss.item(), entropy=entropy.item(), total=loss.item(),clip_fraction=float(((ratio.detach()<.8)|(ratio.detach()>1.2)).float().mean()),rollout_epoch=self.ppo_epoch)\n        update = optimizer_step(loss,self.ppo_opt,self.actor.mean.bias,'Actor.mean.bias[0]（与Critic联合）',.5)\n        return dict(algorithm='PPO', source=f'旧策略在线采样256步；本rollout第{self.ppo_epoch}/4次更新', batch=256,\n                    formulas=['δ=r+0.99V(s′)−V(s)', 'GAE=δ+0.99×0.95×下一个GAE（episode边界截断）',\n                              'A标准化=(GAE−均值)/标准差；target=GAE+旧V',\n                              'ρ=exp(logπ新−logπ旧)；Lπ=−mean(min(ρA,clip(ρ)A))',\n                              'L=Lπ+0.5Lvalue−0.01H'],sample=sample_trace,losses=losses,updates=[update],gradient_check=gradient_check,\n                    note='小网络PPO：同一rollout做4次全批更新，每次更新后独立仿真。第1步ratio=1，后续步可触发裁剪；用满4步后重新采样。熵项在未压缩高斯空间计算。')\n\n    def offline_update(self):\n        s,a,r,ns,done = self.batch()\n        # 固定数据用于BC监督或IQL价值学习。评估轨迹不在self.buffer中。\n        updates, losses = [], {}\n        weights = torch.ones_like(r)\n        sample = dict(state=s[0].tolist(), next_state=ns[0].tolist(), action=float(a[0,0]),reward=float(r[0,0]),terminated=bool(done[0,0]))\n        if self.algo == 'iql':\n            with torch.no_grad():\n                q_data = torch.minimum(self.tq1(torch.cat([s,a],1)),self.tq2(torch.cat([s,a],1)))\n            value = self.value(s)\n            diff = q_data-value\n            asym = torch.where(diff>0,.7,.3)\n            vl = (asym*diff.square()).mean()\n            sample.update(q=float(q_data[0,0]),v_before=float(value[0,0].detach()),diff=float(diff[0,0].detach()),\n                          expectile_weight=float(asym[0,0]),expectile_sample_loss=float((asym*diff.square())[0,0].detach()))\n            updates.append(optimizer_step(vl,self.v_opt,self.value[-1].bias,'V.output.bias[0]'))\n            with torch.no_grad():\n                target = r+.99*(1-done)*self.value(ns)\n                advantage = q_data-self.value(s)\n                weights = torch.exp(3*advantage).clamp(max=100)\n            xu=torch.cat([s,a],1)\n            ql=((self.q1(xu)-target).square()+(self.q2(xu)-target).square()).mean()\n            updates.append(optimizer_step(ql,self.q_opt,self.q1[-1].bias,'Q1.output.bias[0]（Q1/Q2联合）'))\n            with torch.no_grad():\n                for src,dst in [(self.q1,self.tq1),(self.q2,self.tq2)]:\n                    for p,tp in zip(src.parameters(),dst.parameters()):tp.lerp_(p,.005)\n            sample.update(q_target=float(target[0,0]),advantage=float(advantage[0,0]),weight=float(weights[0,0]))\n            losses.update(value=vl.item(),q=ql.item())\n        prediction=self.actor.deterministic(s)\n        mse=(prediction-a).square()\n        actor_loss=(weights*mse).mean()\n        # 与IL的链式法则完全相同，仅IQL多一个已detach的样本权重w。\n        # π=2tanh(μ)，所以∂π/∂b=2(1−(π/2)²)。\n        d_action = 2 * (1-(prediction.detach()/2).square())\n        grad_samples = 2 * weights * (prediction.detach()-a) * d_action\n        gradient_check = dict(formula='g_b=mean(2w(π−a)×2(1−(π/2)²))；BC中w=1',\n                              sample_error=float((prediction.detach()-a)[0,0]),\n                              sample_daction=float(d_action[0,0]),sample_weight=float(weights[0,0]),\n                              sample_gradient=float(grad_samples[0,0]),analytic_batch_gradient=float(grad_samples.mean()))\n        sample.update(prediction=float(prediction[0,0].detach()),mse=float(mse[0,0].detach()),\n                      weight=float(weights[0,0]),weighted_error=float((weights*mse)[0,0].detach()))\n        updates.append(optimizer_step(actor_loss,self.actor_opt,self.actor.mean.bias,'Actor.mean.bias[0]'))\n        losses['actor']=actor_loss.item()\n        return dict(algorithm=self.algo.upper(),source='初始化冻结的2048条脚本教师+随机转移',batch=64,\n                    data_hash=self.data_hash,sample=sample,losses=losses,updates=updates,gradient_check=gradient_check,\n                    formulas=['BC: L=mean((2tanh(μ(s))−a数据)²)' ] if self.algo=='bc' else\n                             ['V: δ=min(Qtarget1,Qtarget2)−V；L=mean(|0.7−1[δ<0]|δ²)',\n                              'Q: y=r+0.99(1−terminated)V新(s′)；L=mean((Q1−y)²+(Q2−y)²)',\n                              'target Q ← 0.995 target Q+0.005 Q新',\n                              'Actor: w=min(exp(3(Qtarget数据−V新)),100)；L=mean(w(π(s)−a数据)²)'],\n                    note='每轮V、Q、Actor各更新一次。BC只更新Actor。训练不再与环境交互；每轮之后的独立仿真只做评估。')\n\n    def sac_update(self):\n        self.collect(64)\n        s,a,r,ns,done=self.batch()\n        alpha=self.log_alpha.exp().detach()\n        with torch.no_grad():\n            na,nlogp=self.actor.sample(ns)\n            soft_q=torch.minimum(self.tq1(torch.cat([ns,na],1)),self.tq2(torch.cat([ns,na],1)))-alpha*nlogp\n            target=r+.99*(1-done)*soft_q\n        qa=torch.cat([s,a],1)\n        ql=((self.q1(qa)-target).square()+(self.q2(qa)-target).square()).mean()\n        updates=[optimizer_step(ql,self.q_opt,self.q1[-1].bias,'Q1.output.bias[0]（Q1/Q2联合）')]\n        # Actor更新期间冻结Q参数，但保留Q对动作的导数，使Actor仍能利用Q学习。\n        for p in list(self.q1.parameters())+list(self.q2.parameters()):p.requires_grad_(False)\n        action,logp=self.actor.sample(s)\n        q_pi=torch.minimum(self.q1(torch.cat([s,action],1)),self.q2(torch.cat([s,action],1)))\n        actor_loss=(alpha*logp-q_pi).mean()\n        # Q对动作的导数由真实Q网络autograd得到，再手推Actor输出偏置的链式梯度。\n        dq_da = torch.autograd.grad(q_pi.sum(),action,retain_graph=True)[0].detach()\n        y=action.detach()/2\n        d_action=2*(1-y.square())\n        d_logp=4*y*(1-y.square())/(2*(1-y.square())+1e-6)\n        grad_samples=alpha*d_logp-dq_da*d_action\n        gradient_check=dict(formula='g_b=mean(α·∂logπ/∂μ − (∂Q/∂a)·2(1−tanh²z))',\n                            sample_dlogp=float(d_logp[0,0]),sample_dqda=float(dq_da[0,0]),\n                            sample_daction=float(d_action[0,0]),sample_gradient=float(grad_samples[0,0]),\n                            analytic_batch_gradient=float(grad_samples.mean()))\n        sample=dict(state=s[0].tolist(), next_state=ns[0].tolist(), action=float(a[0,0]), reward=float(r[0,0]),terminated=bool(done[0,0]),alpha=float(alpha),\n                    next_logp=float(nlogp[0,0]),soft_next_q=float(soft_q[0,0]),q_target=float(target[0,0]),\n                    logp=float(logp[0,0].detach()),q_pi=float(q_pi[0,0].detach()),\n                    actor_sample_loss=float((alpha*logp-q_pi)[0,0].detach()))\n        updates.append(optimizer_step(actor_loss,self.actor_opt,self.actor.mean.bias,'Actor.mean.bias[0]'))\n        for p in list(self.q1.parameters())+list(self.q2.parameters()):p.requires_grad_(True)\n        # 目标熵为−动作维度=−1。logp.detach：温度更新不再改变Actor。\n        alpha_loss=-(self.log_alpha*(logp.detach()-1)).mean()\n        updates.append(optimizer_step(alpha_loss,self.alpha_opt,self.log_alpha,'log_alpha[0]'))\n        with torch.no_grad():\n            for src,dst in [(self.q1,self.tq1),(self.q2,self.tq2)]:\n                for p,tp in zip(src.parameters(),dst.parameters()):tp.lerp_(p,.005)\n        return dict(algorithm='SAC',source=f'在线经验池{len(self.buffer)}条；本轮新增64步',batch=64,\n                    sample=sample,losses=dict(q=ql.item(),actor=actor_loss.item(),temperature=alpha_loss.item()),updates=updates,gradient_check=gradient_check,\n                    formulas=['y=r+0.99(1−terminated)(min Qtarget(s′,a′)−αlogπ(a′|s′))',\n                              'Q: mean((Q1−y)²+(Q2−y)²)', 'Actor: mean(αlogπ(a|s)−min Q新(s,a))',\n                              '温度: −mean(logα×detach(logπ−1))；α=exp(logα)',\n                              'target Q ← 0.995 target Q+0.005 Q新'],\n                    note='同一轮Q、Actor、温度各做一次Adam更新，接着仿真。logπ是连续概率密度的对数，可以为正。')\n\n    def update(self):\n        check_memory()\n        if self.round>=50:raise RuntimeError('本次会话已达到50轮，请创建新实验继续学习。')\n        before=self.actor_hash()\n        old_parameters={name:p.detach().clone() for name,p in self.actor.named_parameters()}\n        if self.algo=='ppo':trace=self.ppo_update()\n        elif self.algo=='sac':trace=self.sac_update()\n        else:trace=self.offline_update()\n        actor_update=next(x for x in trace['updates'] if x['name'].startswith('Actor.'))\n        trace['gradient_check']['autograd_batch_gradient']=actor_update['grad_raw']\n        trace['gradient_check']['difference']=trace['gradient_check']['analytic_batch_gradient']-actor_update['grad_raw']\n        self.round+=1\n        # 核心承诺：每一次完整算法更新后，立刻运行一次真实环境评估。\n        evaluation=self.evaluate()\n        changes=[]\n        for name,p in self.actor.named_parameters():\n            prev=old_parameters[name]\n            changes.append(dict(name=name,shape=list(p.shape),before=prev.flatten().tolist(),\n                                after=p.detach().flatten().tolist(),\n                                grad=None if p.grad is None else p.grad.detach().flatten().tolist(),\n                                delta_norm=float((p.detach()-prev).norm())))\n        record=dict(round=self.round,evaluation=evaluation,trace=trace,actor_hash=self.actor_hash(),previous_actor_hash=before,\n                    parameters=changes)\n        self.persist(record)\n        self.history.append(record)\n        return record\n\n    def persist(self,record):\n        \"\"\"每轮独立落盘：数值、实际轨迹、全部网络与优化器、训练环境和随机数状态。\"\"\"\n        # 这些文件用于审计/复现。UI不在出错后自动加载并继续训练。\n        (self.folder/f'round-{record[\"round\"]:03}.json').write_text(json.dumps(record,ensure_ascii=False,indent=2,allow_nan=False))\n        payload=dict(actor=self.actor.state_dict(),value=self.value.state_dict(),q1=self.q1.state_dict(),q2=self.q2.state_dict(),\n                     tq1=self.tq1.state_dict(),tq2=self.tq2.state_dict(),log_alpha=self.log_alpha.detach(),\n                     ppo_opt=self.ppo_opt.state_dict(),actor_opt=self.actor_opt.state_dict(),q_opt=self.q_opt.state_dict(),\n                     v_opt=self.v_opt.state_dict(),alpha_opt=self.alpha_opt.state_dict(),round=self.round,\n                     algo=self.algo,seed=self.seed,lr=self.lr,torch_rng=torch.get_rng_state(),np_rng=self.rng.bit_generator.state,\n                     env_state=self.env.unwrapped.state.copy(),elapsed_steps=self.env._elapsed_steps,\n                     env_rng=self.env.unwrapped.np_random.bit_generator.state,buffer=self.buffer,\n                     ppo_cache=self.ppo_cache,ppo_epoch=self.ppo_epoch)\n        torch.save(payload,self.folder/f'round-{record[\"round\"]:03}.pt')\n        (self.folder/'config.json').write_text(json.dumps(dict(algorithm=self.algo,seed=self.seed,lr=self.lr,\n              gamma=.99,evaluation_seed=10000,evaluation_steps=200,round_definition='每个相关优化器各更新一次，然后仿真一次',\n              source_hash=hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),data_hash=self.data_hash if hasattr(self,'data_hash') else None),ensure_ascii=False,indent=2))\n\n    def close(self):\n        self.env.close()\n", "teaching_server.py": "\"\"\"本机教学服务：静态网页 + 串行、可暂停的真实参数更新 API。\n\n只接受本机、同源 JSON 写请求，不执行网页提供的任意命令或文件路径。\n所有训练在同一CPU/内存受限服务内的单个后台线程运行，GET请求不训练。\n\"\"\"\nimport json\nimport threading\nimport traceback\nfrom concurrent.futures import ThreadPoolExecutor\nfrom http.server import SimpleHTTPRequestHandler, ThreadingHTTPServer\nfrom pathlib import Path\nfrom urllib.parse import parse_qs, urlparse\n\nfrom live_engine import Experiment\n\nROOT=Path(__file__).resolve().parent\nLOCK=threading.RLock()\nPOOL=ThreadPoolExecutor(max_workers=1)\nSTOP=threading.Event()\nEXPERIMENT=None\nSTATE=dict(busy=False,error=None,operation='idle',finished=0,requested=0)\n\n\ndef status():\n    with LOCK:\n        result=dict(STATE)\n        result['available']=True\n        if EXPERIMENT is not None:\n            e=EXPERIMENT\n            result.update(session=e.name,algo=e.algo,seed=e.seed,lr=e.lr,round=e.history[-1]['round'],\n                folder=str(e.folder),history=[dict(round=x['round'],return_=x['evaluation']['return_'],actor_hash=x['actor_hash']) for x in e.history])\n        return result\n\n\ndef work(action,config):\n    global EXPERIMENT\n    try:\n        if action=='create':\n            new=Experiment(config['algo'],config['seed'],config['lr'])\n            with LOCK:\n                if EXPERIMENT is not None:EXPERIMENT.close()\n                EXPERIMENT=new\n                STATE['finished']=1\n        else:\n            for _ in range(config['count']):\n                if STOP.is_set():break\n                # update包含真梯度计算、Adam、真实200步仿真和落盘，不能跳过中间轮。\n                EXPERIMENT.update()\n                with LOCK:STATE['finished']+=1\n    except Exception as exc:\n        with LOCK:STATE['error']=str(exc)\n        traceback.print_exc()\n    finally:\n        with LOCK:\n            STATE['busy']=False\n            STATE['operation']='paused' if STOP.is_set() else 'idle'\n\n\nclass Handler(SimpleHTTPRequestHandler):\n    def __init__(self,*args,**kwargs):super().__init__(*args,directory=str(ROOT),**kwargs)\n\n    def json_reply(self,data,code=200):\n        encoded=json.dumps(data,ensure_ascii=False,allow_nan=False).encode()\n        self.send_response(code)\n        self.send_header('Content-Type','application/json; charset=utf-8')\n        self.send_header('Cache-Control','no-store')\n        self.send_header('Content-Length',str(len(encoded)))\n        self.end_headers();self.wfile.write(encoded)\n\n    def do_GET(self):\n        path=urlparse(self.path)\n        if path.path=='/api/live/status':return self.json_reply(status())\n        if path.path=='/api/live/round':\n            try:\n                query=parse_qs(path.query);index=int(query['index'][0])\n                with LOCK:\n                    if EXPERIMENT is None or not 0<=index<len(EXPERIMENT.history):raise ValueError('该轮尚未完成')\n                    record=EXPERIMENT.history[index]\n                return self.json_reply(record)\n            except (ValueError,KeyError) as exc:return self.json_reply(dict(error=str(exc)),404)\n        # 目录含虚拟环境、历史记录等，禁用目录列表及隐藏文件请求。\n        from urllib.parse import unquote\n        if any(part.startswith('.') for part in unquote(path.path).split('/') if part):return self.send_error(403)\n        return super().do_GET()\n\n    def list_directory(self,path):\n        self.send_error(403,'Directory listing disabled')\n\n    def do_POST(self):\n        if self.path not in ['/api/live/create','/api/live/update','/api/live/stop']:\n            return self.json_reply(dict(error='接口不存在'),404)\n        host=self.headers.get('Host','')\n        origin=self.headers.get('Origin')\n        allowed=['127.0.0.1:8765','localhost:8765']\n        if host not in allowed or (origin is not None and origin not in ['http://'+h for h in allowed]):\n            return self.json_reply(dict(error='仅支持本机同源请求'),403)\n        if not self.headers.get('Content-Type','').startswith('application/json'):\n            return self.json_reply(dict(error='需要JSON请求'),415)\n        try:\n            length=int(self.headers.get('Content-Length','0'))\n            if not 0<length<4096:raise ValueError('请求体大小不正确')\n            data=json.loads(self.rfile.read(length))\n            if not isinstance(data,dict):raise ValueError('需要JSON对象')\n            action=self.path.rsplit('/',1)[1]\n            with LOCK:\n                if action=='stop':\n                    STOP.set()\n                    return self.json_reply(dict(message='将在当前完整更新和仿真落盘后暂停'))\n                if STATE['busy']:return self.json_reply(dict(error='已有操作正在运行，请等待或暂停'),409)\n                if action=='create':\n                    algo=data['algo'];seed=data['seed'];lr=data['lr']\n                    if algo not in ['bc','ppo','sac','iql']:raise ValueError('算法不支持')\n                    if type(seed) is not int or not 0<=seed<2**31:raise ValueError('种子应为非负整数')\n                    if type(lr) not in [int,float] or not .00001<=lr<=.02:raise ValueError('学习率范围为1e-5到0.02')\n                    config=dict(algo=algo,seed=seed,lr=lr)\n                else:\n                    if EXPERIMENT is None:raise ValueError('请先创建实验')\n                    if STATE['error']:raise ValueError('上次操作异常，请创建新实验后继续')\n                    count=data['count']\n                    if type(count) is not int or not 1<=count<=10:raise ValueError('单次更新轮数应为1到10')\n                    if EXPERIMENT.round+count>50:raise ValueError('本次会话最多50轮，请减少轮数或新建实验')\n                    config=dict(count=count)\n                STOP.clear()\n                STATE.update(busy=True,error=None,operation=action,finished=0,requested=1 if action=='create' else config['count'])\n                POOL.submit(work,action,config)\n            return self.json_reply(dict(accepted=True),202)\n        except (ValueError,KeyError,TypeError,json.JSONDecodeError) as exc:\n            return self.json_reply(dict(error=str(exc)),400)\n\n\nif __name__=='__main__':\n    print('教学服务：http://127.0.0.1:8765/（逐轮更新任务严格串行）',flush=True)\n    server=ThreadingHTTPServer(('127.0.0.1',8765),Handler)\n    try:server.serve_forever()\n    finally:\n        STOP.set();POOL.shutdown(wait=True);server.server_close()\n"};
const EXISTING_RESULTS={"iql-smoke": {"returns": [-1003.7549503051887, -1074.4758229308263], "mean": -1039.1153866180075, "std": 35.36043631281882}, "ppo-smoke": {"returns": [-1054.4593447908192, -1015.2116992613707], "mean": -1034.8355220260948, "std": 19.623822764724252}};
